ALL_ERAS = ["1960s", "1970s", "1980s", "1990s", "2000s", "2010s", "2020s"]


def _pts(rows, nd=3):
    return [[str(y), round(float(v), nd)] for y, v in rows]


def _ind(id_, title, unit, desc, cat, src, rows, note=None, eras=ALL_ERAS, nd=3, **kw):
    d = {"id": id_, "title": title, "unit": unit, "frequency": "annual", "description": desc, "category": cat,
         "series": [{"country": "KR", "label": "한국", "sourceIds": src, "points": _pts(rows, nd)}], "eraIds": eras}
    if note:
        d["note"] = note
    d.update(kw)
    return d


