def merge_tfr(ind):
    """기존 tfr-kr(2015~, 통계청 보도)에 1960~2016 세계은행 값을 붙인다. 겹치는 2015년은 기존 값 유지."""
    have = {p[0] for p in ind["series"][0]["points"]}
    add = [[str(y), v] for y, v in TFR_WB if str(y) not in have]
    ind["series"][0]["points"] = sorted(add + ind["series"][0]["points"], key=lambda p: p[0])
    ind["series"][0]["sourceIds"] = ["fred-kr-tfr"] + ind["series"][0]["sourceIds"]
    ind["note"] = "1960~2016년(2015년 제외)은 세계은행 계열, 2015·2017년 이후는 통계청 발표 보도. 겹치는 연도(2015·2018·2023)에서 두 출처 차이 0.01명 이하"
    ind["eraIds"] = ALL_ERAS
    ind["description"] = "여성 1명이 평생 낳을 것으로 예상되는 아이 수. 1960년 약 6명에서 1983년 인구 유지 수준(2.1명) 아래로, 2018년 1명 아래로 떨어졌다."


